(7763929, 1286775, 38162, '<td valign="top">Yes, but not yours.</td>', 'Yes, but not yours.', '2024-02-19 18:36:46.000000', NULL, 1),
(7763932, 1286700, 138630, '<td valign="top">The moment is perfect - and perfectly documented.  A fine wildlife capture.  But beyond that, there''s the mirrored reflection and the neck and splash coming in from (or going out to) the corners on diagonals.  This is wonderful.  10</td>', 'The moment is perfect - and perfectly documented.  A fine wildlife capture.  But beyond that, there''s the mirrored reflection and the neck and splash coming in from (or going out to) the corners on diagonals.  This is wonderful.  10', '2024-02-19 22:13:22.000000', NULL, 1),
(7763933, 1286790, 138630, '<td valign="top">She is beautiful, strong, dramatic.  I love the way you''ve chosen to place the vanishing point low on her forehead so the city radiates out from her.  If I had any criticism, it would be that the faint bit of building left across her teeth looks, at a glance, like braces.  That doesn''t work for me for this look.  10</td>', 'She is beautiful, strong, dramatic.  I love the way you''ve chosen to place the vanishing point low on her forehead so the city radiates out from her.  If I had any criticism, it would be that the faint bit of building left across her teeth looks, at a glance, like braces.  That doesn''t work for me for this look.  10', '2024-02-19 22:16:26.000000', NULL, 1),
(7763934, 1286780, 138630, '<td valign="top">Dreamy, ethereal, interesting tones.  Lovely still life.  9</td>', 'Dreamy, ethereal, interesting tones.  Lovely still life.  9', '2024-02-19 22:17:01.000000', NULL, 1),
(7763935, 1286556, 138630, '<td valign="top">Beautiful low key portrait - the lighting is perfect and the pose striking. 8</td>', 'Beautiful low key portrait - the lighting is perfect and the pose striking. 8', '2024-02-19 22:17:39.000000', NULL, 1),
(7763936, 1286748, 138630, '<td valign="top">Tones are perfect as is his position well off center in the light.  What an amazing assemblage of tools!  Great tones.  Lovely.  I do feel I''ve seen this before but I''m sure it was just very similar.  Still, that lessens the impact a bit for me.  8</td>', 'Tones are perfect as is his position well off center in the light.  What an amazing assemblage of tools!  Great tones.  Lovely.  I do feel I''ve seen this before but I''m sure it was just very similar.  Still, that lessens the impact a bit for me.  8', '2024-02-19 22:19:30.000000', NULL, 1),
(7763937, 1286773, 138630, '<td valign="top">The two deer, positioned as they are, certainly draw the eye.  But for me it''s the light, the mist, the waving grasses that hold my attention.  I''d almost prefer the deer weren''t so strangely positioned as the bizarre, two-headed look is quite at odds with the mood here.  9</td>', 'The two deer, positioned as they are, certainly draw the eye.  But for me it''s the light, the mist, the waving grasses that hold my attention.  I''d almost prefer the deer weren''t so strangely positioned as the bizarre, two-headed look is quite at odds with the mood here.  9', '2024-02-19 22:21:10.000000', NULL, 1),
